function requestTable(rs){return rs.length?`<div class="tablewrap"><table><thead><tr><th>EMPLOYEE / REQUEST</th><th>TYPE</th><th>STATUS</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr class="clickable" onclick="requestDetail('${r.id}')"><td><div class="person"><span class="avatar">${initials(pby(r.person).name)}</span><div>${esc(pby(r.person).name)}<small>${r.id} · ${r.date}</small></div></div></td><td>${esc(r.type)}${['Leave','Shift allowance'].includes(r.type)?`<small>${esc(leaveTypeLabel(r))}</small>`:''}<small>${esc(r.owner)}</small></td><td>${badge(r.status)}</td><td>${btn('Open →',`requestDetail('${r.id}')`,'link')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">✓ You’re all caught up. No requests in this view.</div>'}
function work(){let rs=visibleRequests().filter(r=>(tab==='All requests'||(tab==='Pending'?['Pending','Verification'].includes(r.status):r.status===tab))&&(!query||`${r.id} ${pby(r.person).name} ${r.type} ${r.leaveTypeName||''}`.toLowerCase().includes(query.toLowerCase())));return heading('My work','A clear view of your requests, reviews, and next steps.',btn('＋ New request',"requestForm()",'primary'))+card('Requests & approvals',`<div class="tabs">${['All requests','Pending','Approved','Draft','Returned','Clarification','Completed'].map(t=>btn(t,`tab='${t}';render()`,tab===t?'selected':'')).join('')}</div><div class="toolbar" style="padding-top:17px"><input aria-label="Filter requests" placeholder="Search by employee, type or request ID" value="${esc(query)}" onchange="applyQuery(this.value)" onkeydown="if(event.key==='Enter')applyQuery(this.value)">${btn('Search',"searchRequests()")}${btn('Save view',"saveView()")}${btn('Saved views',"showViews()")}${btn('Export CSV',"exportRequests()")}</div>${requestTable(rs)}<div class="cardfoot"><span>${rs.length} requests · ${state.views.length} saved views</span><span>Page 1 of 1</span></div>`)}
function peoplePage(){if(profileTab==='Profile')profileTab='Overview';let ps=visiblePeople().filter(p=>`${p.name} ${p.id} ${p.dept}`.toLowerCase().includes(query.toLowerCase())&&(filter==='All'||currentLocation(p)===filter));return heading('People & service records','One connected record for every person and assignment.')+card('Employee directory',`<div class="toolbar"><input aria-label="Search employee directory" placeholder="Search name, employee ID or department" value="${esc(query)}" onchange="applyQuery(this.value)" onkeydown="if(event.key==='Enter')applyQuery(this.value)"><select aria-label="Filter by location" onchange="applyLocation(this.value)">${['All',...new Set(visiblePeople().map(p=>currentLocation(p)))].map(l=>`<option ${filter===l?'selected':''}>${l}</option>`).join('')}</select>${btn('Search',"searchDirectory()")}${btn('Export',"download('people.csv',peopleCSV())")}</div><div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>ROLE / CATEGORY</th><th>LOCATION</th><th>RELATIONSHIP</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr class="clickable" onclick="openProfile('${p.id}')"><td><div class="person"><span class="avatar">${initials(p.name)}</span><div>${p.name}<small>${p.id}</small></div></div></td><td>${p.job}<small>${p.category} · ${p.grade}</small></td><td>${esc(currentLocation(p))}<small>${p.dept}</small></td><td>${badge(p.employment)}</td><td>${btn('Open →',`openProfile('${p.id}')`,'link')}</td></tr>`).join('')}</tbody></table></div>${!ps.length?'<div class="empty">No matching employees.</div>':''}<div class="cardfoot"><span>${ps.length} records · scope: ${isAdmin()?'organisation':role==='Contractor administrator'?'assigned contractor':'self'}</span><span>Page 1 of 1</span></div>`)}
function openProfile(id){if(!visiblePeople().some(p=>p.id===id)){toast('This employee is outside your demo role’s scope.');return}profileId=id;profileTab='Overview';profileModal()}function profileModal(){const p=pby(profileId);let fields=profileTab==='Employment'?[['Employment relationship',p.employment],['Category',p.category],['Grade',p.grade],['Position',p.job],['Department',p.dept],['Location',currentLocation(p)],['Working pattern',p.shift],['Reporting officer','Rajesh Kumar'],['Contractor',p.employment==='Agency contract'?'Shakti Technical Services':'Not applicable']]:[['Employee ID',p.id],['Designation',p.job],['Department',p.dept],['Location',currentLocation(p)],['Work email',p.employment==='Agency contract'?'Not assigned':'••••@example.invalid'],['Contact number','••••••4821'],['Bank account','•••• •••• 1290'],['Emergency contact','Restricted personal record'],['Employment relationship',p.employment]];let c=profileTab==='Service book'?`<div class="timeline">${[...(state.events[p.id]||[]),{date:'01 Apr 2024',title:'Grade revision recorded',note:`Assigned to ${p.grade} · Office order EST/2024/041`},{date:'01 Jul 2021',title:'Posting confirmed',note:p.location},{date:'15 Jun 2018',title:'Initial appointment',note:`${p.job} · Illustrative service history`}].map(e=>`<div class="event"><small>${esc(e.date)}</small><p><strong>${esc(e.title)}</strong></p><small>${esc(e.note)}</small></div>`).join('')}</div>`:profileTab==='Skills'?`<div class="row"><div><strong>Electrical safety authorisation</strong><p>Valid until 12 Nov 2026 · Renewal required</p></div>${badge('Pending')}</div><div class="row"><div><strong>Workplace safety induction</strong><p>Completed · 15 Apr 2026</p></div>${badge('Completed')}</div>`:profileTab==='Documents'?`<div class="row"><div>Appointment order<p>Illustrative document · no personal data</p></div>${btn('Download',"download('appointment-order.txt','DEMONSTRATION DOCUMENT — Appointment order for '+pby(profileId).name)")}</div>`:profileTab==='Dependants'?'<div class="callout" style="margin:24px">Personal dependant and nomination records are masked in this shared demonstration.</div>':`<div class="details">${fields.map(f=>`<div><label>${f[0]}</label><strong>${esc(f[1])}</strong></div>`).join('')}</div>`;modal('Employee record',`<div class="profile"><span class="avatar">${initials(p.name)}</span><div><h2>${p.name}</h2><p class="sub" style="margin:7px 0">${p.job} · ${p.id}</p>${badge(p.category)}</div></div><div class="tabs">${['Overview','Employment','Service book','Skills','Documents','Dependants'].map(t=>btn(t,`profileTab='${t}';profileModal()`,profileTab===t?'selected':'')).join('')}</div>${c}`,'')}
function timePage(){return heading('Time & workforce','Attendance, shifts, and leave across your workplace.',btn('＋ New request',"requestForm('Attendance correction')",'primary'))+`<div class="stats">${stat('Today’s schedule',person().shift,'30 Oct 2026')}${stat('Recorded attendance','09:02','Entry punch · illustrative')}${stat('Leave balance',annualLeaveAvailable(),'Annual leave · Available to request')}${stat('Open corrections',visibleRequests().filter(r=>r.type==='Attendance correction'&&r.status==='Pending').length,'Awaiting reporting officer')}</div>`+card('Workforce calendar',`<div class="tabs">${['Attendance','Shift roster','Leave','Overtime'].map(t=>btn(t,`tab='${t}';render()`,(tab===t||(tab==='All requests'&&t==='Attendance'))?'selected':'')).join('')}</div>${tab==='Shift roster'?roster():tab==='Leave'?`${leaveBalancesOverview()}${requestTable(visibleRequests().filter(r=>['Leave','Shift allowance'].includes(r.type)))}`:tab==='Overtime'?`<div class="row"><p>Overtime requires authorisation and verification under configured company policy.</p>${btn('Request overtime',"requestForm('Overtime')")}</div>${requestTable(visibleRequests().filter(r=>r.type==='Overtime'))}`:`<div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>DATE</th><th>IN</th><th>OUT</th><th>STATUS</th></tr></thead><tbody>${visiblePeople().map((p,i)=>`<tr><td>${p.name}<small>${p.shift}</small></td><td>29 Oct 2026</td><td>09:02</td><td>${p.id==='PSU-4210'&&!state.attendance[p.id]?'Missing':'17:30'}</td><td>${badge(p.id==='PSU-4210'&&!state.attendance[p.id]?'Pending':'Completed')}</td></tr>`).join('')}</tbody></table></div><div class="row"><p>Missing a punch? Submit a correction with the hours worked.</p>${btn('Request correction',"requestForm('Attendance correction')")}</div>`}`)}
function roster(){return `<div class="toolbar" style="padding-top:18px"><span class="sub">Week of 02–08 Nov 2026 · Bhilai plant · Illustrative roster</span>${isAdmin()?btn('Edit assignment',"editRoster() "):''}</div><div class="tablewrap"><table class="roster"><thead><tr><th>TEAM MEMBER</th>${['Mon 02','Tue 03','Wed 04','Thu 05','Fri 06','Sat 07','Sun 08'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${visiblePeople().slice(0,6).map((p,i)=>`<tr><td>${p.name}<small>${p.job}</small></td>${Array.from({length:7},(_,d)=>`<td><span class="shift ${d>4?'off':''}">${d>4?'Rest':esc(state['shift-'+p.id]||(['General','Shift A','Shift B'][i%3]))}<br>${d>4?'—':i%3===2?'14:00–22:00':'06:00–14:00'}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function payPage(){return heading('Pay & benefits','Your pay information, claims, and payroll operations.',btn('View my payslip',"payslip()",'primary'))+`<div class="callout">Demonstration only. Amounts and calculations are illustrative; applicable PSU payroll rules must be configured and validated.</div>`+(role==='Payroll officer'||role==='HR officer'?card('October payroll · Exception workspace',`<div class="row"><div><strong>Input verification</strong><p>${state.payroll.filter(x=>x.status==='Pending').length} exceptions require attention before approval.</p></div>${btn('Review closure',"payrollClose()")}</div><div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>EXCEPTION</th><th>IMPACT</th><th>STATUS</th><th></th></tr></thead><tbody>${state.payroll.map(e=>`<tr><td>${pby(e.person).name}</td><td>${e.issue}</td><td>${money(e.amount)}</td><td>${badge(e.status)}</td><td>${btn('Investigate',`payException('${e.id}')`,'link')}</td></tr>`).join('')}</tbody></table></div>`):'')+`<div class="split">${card('My pay statements',`<div class="row"><div><strong>October 2026</strong><p>Monthly pay statement · illustrative</p></div>${btn('View statement',"payslip()")}</div><div class="row"><div><strong>September 2026</strong><p>Monthly pay statement · illustrative</p></div>${btn('View statement',"payslip('September')")}</div>`)}${card('Claims & reimbursements',`<div class="row"><div><strong>Submit a claim</strong><p>Travel, expenses, and company-defined reimbursements.</p></div>${btn('＋ Claim',"requestForm('Claim')")}</div>${requestTable(visibleRequests().filter(r=>r.type==='Claim'))}`)}</div>`}
function lifecycle(){return heading('Employee lifecycle','Every service event, with a clear record and next step.',btn('Initiate transfer',"requestForm('Transfer')",'primary'))+`<div class="stats">${stat('Active transfers',state.requests.filter(r=>r.type==='Transfer'&&r.status!=='Completed').length,'Establishment workflow')}${stat('Joining this month','3','Illustrative forecast')}${stat('Retiring in 90 days','8','Illustrative forecast')}${stat('Open clearances','4','Illustrative count')}</div>`+card('Transfers & postings',`<div class="callout" style="margin:0 20px 20px">Sample process: verification → competent-authority approval → office order → relieving → joining → service-record update.</div>${requestTable(state.requests.filter(r=>r.type==='Transfer'))}`)+card('Other lifecycle services',`<div class="row"><div><strong>Appointment, confirmation, promotion & retirement</strong><p>Configure the company’s rules before enabling these workflows. These journeys are not implemented in this prototype.</p></div>${badge('Planned')}</div>`)}
function learning(){return heading('Performance & learning','Build capability. Keep qualifications current.')+`<div class="split">${card('Qualifications requiring attention',`<div class="row"><div><strong>Meena Patel · Electrical safety</strong><p>Authorisation expires 12 Nov 2026 · Maintenance workshop</p></div>${btn('Review',"qualification()",'primary')}</div><div class="row"><div><strong>Rajesh Kumar · First aid</strong><p>Certification expires 24 Nov 2026</p></div>${btn('Review',"qualification('Rajesh Kumar')")}</div>`)}${card('Assigned learning',`<div class="row"><div><strong>Safety refresher 2026</strong><p>Due 15 Nov · Online module · Demo content</p></div>${btn(state.training?'Completed':'Complete demo',"state.training=true;save();render();toast('Demo learning completion recorded')")}</div><div class="row"><div><strong>Performance review cycle</strong><p>Company-configurable appraisal and APAR stages.</p></div>${badge('Planned')}</div>`)}</div>`}
function services(){return heading('Employee services','Find support and track every request.')+onboardingSection()+`<div class="stats">${[['Service certificate','Employment and service confirmation','Certificate'],['Travel reimbursement','Submit travel expenses','Claim'],['HR helpdesk','Ask for help or clarification','Helpdesk'],['Confidential grievance','Restricted HR case handling','Grievance']].map(a=>`<div class="stat"><h3>${a[0]}</h3><p class="sub" style="min-height:35px">${a[1]}</p>${btn(a[2]==='Grievance'?'About access':'Start request →',a[2]==='Grievance'?"grievance()":`requestForm('${a[2]}')`,'link')}</div>`).join('')}</div>`+card('My service requests',requestTable(visibleRequests().filter(r=>['Certificate','Claim','Helpdesk'].includes(r.type))))}
function org(){return heading('Organisation & positions','Understand your structure and staffing needs.')+`<div class="stats">${stat('Sanctioned positions','1,320','Illustrative organisation total')}${stat('Filled positions','1,250','94.7% positions filled')}${stat('Vacancies','70','Across 5 locations')}${stat('Locations','5','Office, plant, workshop & field')}</div>`+card('NRL · Demonstration organisation structure',`<div class="row"><div><strong>Chairperson & Managing Director</strong><p>Corporate office</p></div>${badge('Leadership')}</div>${['Engineering','Production','Maintenance','Human Resources','Finance'].map((d,i)=>`<div class="row"><div><strong>↳ ${d}</strong><p>${['Corporate office','Bhilai plant','Maintenance workshop','Corporate office','Regional office'][i]}</p></div>${btn('View people',`go('People & Service Records');query='${d}';render()`,'link')}</div>`).join('')}`)}
function reports(){return heading('Reports & insights','Operational information with a path to the underlying records.',btn('Export workforce',"download('workforce.csv',peopleCSV())",'primary'))+`<div class="stats">${stat('Demo people records',people.length,'Current sample dataset')}${stat('Pending cases',pending().length,'Visible within your role')}${stat('Resolved requests',state.requests.filter(r=>['Approved','Completed'].includes(r.status)).length,'Current sample dataset')}${stat('Agency workers',people.filter(p=>p.employment==='Agency contract').length,'Separate employment relationship')}</div>`+card('Workforce by job family',`<div class="tablewrap"><table><thead><tr><th>JOB FAMILY</th><th>PEOPLE</th><th>VIEW</th></tr></thead><tbody>${[...new Set(people.map(p=>p.dept))].map(d=>`<tr><td>${d}</td><td>${people.filter(p=>p.dept===d).length}</td><td>${btn('Open records →',`go('People & Service Records');query='${d}';render()`,'link')}</td></tr>`).join('')}</tbody></table></div>`)}
function admin(){return heading('Administration','Configure company policies, permissions, and connected systems.')+`<div class="callout">Demo role switching changes interface scope only. Production authentication, server-enforced permissions, encrypted storage, and validated policy rules are not implemented.</div><div class="split">${card('Policy & workflow configuration',`<div class="row"><div><strong>Leave policy</strong><p>Maximum request length: ${state.policies.leave} days · demo rule</p></div>${btn('Configure',"policyForm()")}</div><div class="row"><div><strong>Approval delegation</strong><p>${esc(state.delegation||'No delegate configured')}</p></div>${btn('Configure',"delegateForm()")}</div><div class="row"><div><strong>Role scopes</strong><p>Self-service, organisational, and contractor views are demonstrated.</p></div>${badge('Demo')}</div>`)}${card('Integration health · Simulated',`${[['ERP & payroll','Connected'],['Attendance devices','Failed'],['Identity / SSO','Connected'],['Document management','Pending'],['Notifications','Connected'],['Learning & safety','Connected']].map(a=>`<div class="row"><div><strong>${a[0]}</strong><p>Mock connector · no external data exchange</p></div>${badge(a[1])}${a[1]==='Failed'?btn('Retry',"toast('Simulation: device endpoint unavailable. Retry later or upload verified attendance.')",'link'):''}</div>`).join('')}`)}</div>`+card('Audit history',state.audit.length?`<div class="timeline">${state.audit.slice().reverse().map(e=>`<div class="event"><small>${esc(e.date)} · ${esc(e.actor)}</small><p>${esc(e.action)}</p></div>`).join('')}</div>`:'<div class="empty">Actions performed in this demo will appear here.</div>')+`<button onclick="resetDemo()">Reset demo data</button>`}
function modal(title,body,foot=''){const d=$('#dialog');d.classList.remove('leave-dialog','onb-dialog','onb-buttons');d.innerHTML=`<div class="modalhead"><h2>${title}</h2><button onclick="$('#dialog').close()" aria-label="Close dialog">×</button></div><div class="modalbody">${body}</div>${foot?`<div class="modalfoot">${foot}</div>`:''}`;if(!d.open)d.showModal();applyLanguage(d)}function audit(action){state.audit.push({date:new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}),actor:person().name,action})}
function requestForm(type='Leave',existing=null){if(type==='Leave'||type==='Shift allowance')return leaveRequestForm(existing,type);let r=existing||{};let choices=['Leave','Shift allowance','Attendance correction','Overtime','Claim','Certificate','Helpdesk',...(role==='HR officer'?['Transfer']:[])];if(!choices.includes(type))type='Leave';modal(existing?'Edit & resubmit request':'Create a request',`<form id="requestform" onsubmit="submitRequest(event,false,'${r.id||''}')"><div class="formgrid"><label class="field full">Request type<select name="type" onchange="requestForm(this.value)">${choices.map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label><label class="field full">Employee<select name="person">${(role==='HR officer'?visiblePeople():[person()]).map(p=>`<option value="${p.id}" ${r.person===p.id?'selected':''}>${p.name} · ${p.id}</option>`).join('')}</select></label>${type==='Leave'?`<label class="field">From<input name="from" type="date" required value="${r.from||'2026-11-03'}"></label><label class="field">To<input name="to" type="date" required value="${r.to||'2026-11-04'}"></label><div class="field full callout">Annual leave · Available: ${state.balances[r.person||self()]??'not configured'} days. Demo counts calendar days; configure actual holiday and shift policies.</div>`:type==='Claim'?`<label class="field">Amount (INR)<input name="amount" type="number" min="1" max="1000000" required value="${r.amount||''}"></label><label class="field">Expense date<input name="expenseDate" type="date" value="2026-10-29" required></label>`:type==='Transfer'?`<label class="field full">Destination<select name="target">${['Regional office','Corporate office','Bhilai plant','Maintenance workshop','Korba field site'].map(l=>`<option>${l}</option>`).join('')}</select></label>`:`<label class="field">Duty / request date<input name="dutyDate" type="date" value="2026-10-29" required></label>${type==='Attendance correction'?'<label class="field">Correct exit time<input name="exitTime" type="time" value="17:30" required></label>':type==='Overtime'?'<label class="field">Additional hours<input name="hours" type="number" min="1" max="12" value="2" required></label>':''}`}<label class="field full">Reason / details<textarea name="reason" required maxlength="1500" placeholder="Provide the details needed to review this request.">${esc(r.reason||'')}</textarea></label><label class="field full">Supporting document (optional)<input name="attachment" type="file" accept=".pdf,.png,.jpg,.txt"><small class="sub">Demo stores the filename only; no file is uploaded.</small></label>${role==='HR officer'?'<label class="field full">Assisted submission<input name="assisted" placeholder="Optional: employee requested assistance"></label>':''}</div><div class="modalfoot" style="padding:20px 0 0;border:0">${btn('Save draft',`submitRequest(null,true,'${r.id||''}')`)}<button class="primary" type="submit">${existing?'Resubmit request':'Submit request'}</button></div></form>`)}
function submitRequest(ev,draft,id){ev?.preventDefault();const form=$('#requestform');if(!draft&&!form.reportValidity())return;let f=Object.fromEntries(new FormData(form)),days=0;if(f.type==='Leave'||f.type==='Shift allowance'){const validation=window.LeaveModel.validate(state,people,f,{excludeId:id,draft});if(!validation.ok){if(['exhausted','insufficient','unconfigured'].includes(validation.code))showLeaveBalanceAlert(validation);else toast(validation.message);return}days=validation.days;f.leaveType=validation.type.id;f.leaveTypeName=validation.type.name;f.type=validation.type.mode==='allowance'?'Shift allowance':'Leave'}let old=state.requests.find(r=>r.id===id),prefix={Leave:'LV','Shift allowance':'SA','Attendance correction':'AT',Overtime:'OT',Claim:'CL',Transfer:'TR'}[f.type]||'SR';let r={...f,id:id||`${prefix}-2026-${Date.now().toString().slice(-6)}`,date:'30 Oct 2026',days,amount:Number(f.amount)||0,status:draft?'Draft':f.type==='Transfer'?'Verification':'Pending',owner:draft?'Applicant':f.type==='Transfer'?'Establishment':'Reporting officer',stage:0,attachment:f.attachment?.name||old?.attachment||'',history:old?.history||[]};delete r.assisted;delete r.leaveChoice;if(old)r.history.push('30 Oct 2026 · Changes on resubmission: '+(old.reason!==r.reason?'reason updated; ':'')+(old.from!==r.from||old.to!==r.to?'dates updated; ':'')+((old.leaveType||'annual')!==r.leaveType&&r.leaveType?'leave type updated; ':'')+'request reviewed by applicant');r.history.push(`30 Oct 2026 · ${draft?'Draft saved':old?'Resubmitted':'Submitted'} by ${person().name}${f.assisted?' on behalf of '+pby(f.person).name:''}`);if(old)state.requests[state.requests.indexOf(old)]=r;else state.requests.unshift(r);audit(`${r.id}: ${r.status}`);save();$('#dialog').close();go('My Work');toast(draft?'Draft saved.':'Request submitted. Track it in My Work.')}
function canReview(r){return r.person!==self()&&((r.type==='Transfer'&&role==='HR officer')||(r.type!=='Transfer'&&['Supervisor','HR officer'].includes(role)))}const stages=['Establishment verification','Competent-authority approval','Office order','Relieving','Joining','Service-record update'];function requestDetail(id){const r=visibleRequests().find(r=>r.id===id);if(!r)return toast('Request is outside your role’s scope.');const review=canReview(r),active=['Pending','Verification'].includes(r.status);let foot=btn('Close',"$('#dialog').close()");if(['Draft','Returned','Clarification'].includes(r.status)&&r.person===self())foot+=btn(r.status==='Draft'?'Continue draft':'Edit & resubmit',`requestForm('${r.type}',state.requests.find(r=>r.id==='${id}'))`,'primary');if(review&&active)foot+=btn('Return',`decisionForm('${id}','Returned')`)+btn('Clarify',`decisionForm('${id}','Clarification')`)+btn('Reject',`decisionForm('${id}','Rejected')`)+btn(r.type==='Transfer'?'Complete stage':'Approve',`decisionForm('${id}','Approved')`,'primary');modal(r.type+' request',`<div class="requestmeta"><strong>${r.id}</strong>${badge(r.status)}<span>${r.date}</span></div><div class="details" style="padding:0 0 23px"><div><label>Applicant</label><strong>${pby(r.person).name}</strong></div><div><label>Currently with</label><strong>${esc(r.owner)}</strong></div><div><label>Policy reference</label><strong>Demo / ${r.type==='Leave'?'Leave-01':'Service-01'}</strong></div>${r.from?`<div><label>Requested dates</label><strong>${r.from} → ${r.to}</strong></div><div><label>Calendar days</label><strong>${r.days}</strong></div>`:''}${r.amount?`<div><label>Amount</label><strong>${money(r.amount)}</strong></div>`:''}${r.hours?`<div><label>Additional hours</label><strong>${esc(r.hours)}</strong></div>`:''}</div>${['Leave','Shift allowance'].includes(r.type)?`<div class="leave-detail-label"><span>Leave / allowance type</span><strong>${esc(leaveTypeLabel(r))}</strong></div>`:''}<h3>Request details</h3><p data-i18n-user style="line-height:1.7">${esc(r.reason)}</p>${r.target?`<p>Destination: <strong>${esc(r.target)}</strong></p>`:''}${r.attachment?`<div class="callout">Attachment reference: ${esc(r.attachment)} · Filename only in demo</div>`:''}${r.type==='Transfer'?`<h3>Approval stages</h3><div class="timeline">${stages.map((s,i)=>`<div class="event"><p>${i<r.stage?'✓':i===r.stage?'◉':'○'} ${s}</p><small>${i<r.stage?'Completed':i===r.stage?'Current stage':'Upcoming'}</small></div>`).join('')}</div>`:''}<h3>Activity history</h3><div class="timeline">${r.history.map(h=>`<div class="event"><p>${esc(h)}</p></div>`).join('')}</div>${r.status==='Completed'&&r.type==='Transfer'?btn('Download office order',`download('${r.id}-order.txt','DEMONSTRATION OFFICE ORDER\n${r.id}\nTransfer of ${pby(r.person).name} to ${r.target}\nNot an official document.')`):''}`,foot)}
function decisionForm(id,status){const r=state.requests.find(r=>r.id===id);if(!canReview(r))return toast('Switch to an authorised reviewer role.');modal(status==='Approved'?(r.type==='Transfer'?stages[r.stage]:'Approve request'):status==='Returned'?'Return for correction':status==='Clarification'?'Request clarification':'Reject request',`<p>${esc(r.id)} · ${pby(r.person).name}</p><label class="field">${status==='Approved'?'Reviewer note (optional)':'Reason (required)'}<textarea id="decisionnote" placeholder="Explain the decision or information needed."></textarea></label><div class="callout" style="margin-top:16px">This action will be recorded with your demo identity and added to the request history.</div>`,btn('Back',`requestDetail('${id}')`)+btn('Confirm',`applyDecision('${id}','${status}')`,'primary'))}
function applyDecision(id,status){const r=state.requests.find(r=>r.id===id),note=$('#decisionnote').value.trim();if(!canReview(r)||!['Pending','Verification'].includes(r.status))return toast('This request is no longer available for review.');if(status!=='Approved'&&!note)return toast('Please enter a reason.');if(status==='Approved'&&r.type==='Leave'){const result=window.LeaveModel.approve(state,people,r);if(!result.ok)return toast(result.message+' · Please return the request for correction.')}let action=status;if(status==='Approved'&&r.type==='Transfer'){action=stages[r.stage]+' completed';r.stage++;r.status=r.stage===stages.length?'Completed':'Verification';r.owner=stages[r.stage]||'Closed';if(r.status==='Completed'){state.events[r.person]??=[];state.events[r.person].unshift({date:'30 Oct 2026',title:'Transfer and joining recorded',note:`Posted to ${r.target} · ${r.id}`,location:r.target})}}else{r.status=status;r.owner=['Returned','Clarification'].includes(status)?'Applicant':'Closed';if(status==='Approved'&&r.type==='Attendance correction')state.attendance[r.person]=r.exitTime||'17:30'}r.history.push(`30 Oct 2026 · ${action} by ${person().name}${note?' — '+note:''}`);audit(`${id}: ${action}${note?' — '+note:''}`);save();render();requestDetail(id);toast('Decision recorded.')}
function payslip(month='October'){if(role==='Contractor administrator')return toast('PSU employee payslips do not apply to agency workers.');const text=`DEMONSTRATION PAY STATEMENT\n${person().name} · ${month} 2026\nBasic: INR 54,000\nIllustrative allowances: INR 26,000\nIllustrative deductions: INR 10,600\nNet: INR 69,400\nNot an official payslip.`;modal(`${month} 2026 · Pay statement`,`<div class="callout">Illustrative amounts only. This is not a statutory calculation or official payslip.</div><h3>${person().name} · ${self()}</h3><div class="row"><span>Basic pay</span><strong>₹54,000</strong></div><div class="row"><span>Illustrative allowances</span><strong>₹26,000</strong></div><div class="row"><span>Illustrative deductions</span><strong>₹10,600</strong></div><div class="row"><strong>Net pay</strong><strong>₹69,400</strong></div>`,btn('Download statement',`download('demo-payslip.txt',${JSON.stringify(text).replace(/"/g,'&quot;')})`,'primary'))}
function payException(id){if(!['Payroll officer','HR officer'].includes(role))return toast('Payroll review requires an authorised role.');const e=state.payroll.find(e=>e.id===id);modal('Investigate payroll exception',`<div class="requestmeta">${e.id} ${badge(e.status)}</div><h3>${pby(e.person).name}</h3><p>${e.issue}</p><div class="row"><span>Illustrative impact</span><strong>${money(e.amount)}</strong></div><div class="callout" style="margin-top:20px">Check the source input and document the reconciliation. This demo does not calculate or disburse payroll.</div><label class="field">Reconciliation note<textarea id="paynote" placeholder="Record the evidence and resolution."></textarea></label>`,btn('Close',"$('#dialog').close()")+(e.status==='Pending'?btn('Mark verified',`resolvePay('${id}')`,'primary'):''))}function resolvePay(id){const n=$('#paynote').value.trim();if(!n)return toast('Add a reconciliation note.');state.payroll.find(e=>e.id===id).status='Completed';audit(`${id}: verified — ${n}`);save();$('#dialog').close();render();toast('Exception verified.')}function payrollClose(){const n=state.payroll.filter(x=>x.status==='Pending').length;modal('Payroll closure review',`<div class="callout">${n?n+' unresolved exceptions. Resolve all exceptions before requesting closure.':'All demo exceptions are verified. Payroll is ready for the next approval stage.'}</div><p>Disbursement and final payroll approval are not implemented in this prototype.</p>`)}
function qualification(name='Meena Patel'){const scope=visiblePeople().some(p=>p.name===name);if(!scope)return modal('Restricted qualification record','<p>This employee is outside your current role’s scope.</p>');modal('Qualification renewal',`<h3>${name}</h3><p>Electrical safety authorisation · Valid until 12 Nov 2026</p><div class="callout">Review qualification validity before assigning restricted work. A training completion alone does not grant operational authorisation.</div><label class="field">Renewal owner<select id="renewowner"><option>Learning & Development</option><option>Safety officer</option></select></label>`,btn('Assign renewal follow-up',`state.renewal=true;audit('Renewal follow-up assigned');save();$('#dialog').close();toast('Renewal follow-up assigned to '+$('#renewowner').value)`,'primary'))}
function editRoster(){modal('Edit roster assignment',`<div class="formgrid"><label class="field">Employee<select id="rosterperson">${visiblePeople().map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label class="field">Assignment<select id="rostershift"><option>Shift A</option><option>Shift B</option><option>General</option><option>On-call</option></select></label></div><div class="callout" style="margin-top:20px">Demo applies to weekdays in the displayed week. Production assignment must validate rest periods, qualifications, and company rules.</div>`,btn('Save assignment',"state['shift-'+$('#rosterperson').value]=$('#rostershift').value;audit('Roster assignment updated');save();$('#dialog').close();render();toast('Assignment updated')",'primary'))}
function policyForm(){modal('Demo leave policy',`<label class="field">Maximum calendar days per request<input id="maxleave" type="number" min="1" max="90" value="${state.policies.leave}"></label><p class="sub" style="margin-top:15px">Applies to new submissions. Historical requests retain their recorded details.</p>`,btn('Save policy',"savePolicy()",'primary'))}function savePolicy(){const n=Number($('#maxleave').value);if(!Number.isInteger(n)||n<1||n>90)return toast('Enter a whole number between 1 and 90.');state.policies.leave=n;audit('Demo leave policy maximum changed to '+n+' days');save();$('#dialog').close();render()}
function delegateForm(){modal('Approval delegation',`<label class="field">Delegate<select id="delegate"><option>Priya Nair · HR Officer</option><option>Rajesh Kumar · Supervisor</option></select></label><div class="callout" style="margin-top:20px">Configuration preview only. Delegated authorisation and date-bounded routing require production implementation.</div>`,btn('Save demo setting',"state.delegation=$('#delegate').value;audit('Delegation demo setting updated');save();$('#dialog').close();render()",'primary'))}
function grievance(){modal('Confidential grievance access','<div class="callout">This shared prototype does not accept confidential grievance details. Production cases require a separately authorised case team, restricted storage, and controlled notifications.</div><p>No sensitive information should be entered into this demonstration.</p>')}
function notifications(){modal('Notifications',`<div class="row"><div><strong>${pending().length} requests need attention</strong><p>Open My Work to review current requests.</p></div>${btn('Open',"$('#dialog').close();go('My Work')",'link')}</div><div class="row"><div><strong>Qualification renewal due</strong><p>Review assigned training and authorisations.</p></div>${btn('Open',"$('#dialog').close();go('Performance & Learning')",'link')}</div><div class="row"><p>Notifications are simulated; no messages are sent.</p></div>`)}
function searchAll(e){e.preventDefault();const q=$('#globalSearch').value.trim().toLowerCase();if(!q)return;const ps=visiblePeople().filter(p=>`${p.name} ${p.id} ${p.dept}`.toLowerCase().includes(q)),rs=visibleRequests().filter(r=>`${r.id} ${r.type} ${pby(r.person).name}`.toLowerCase().includes(q));modal('Search results',`<h3>People · ${ps.length}</h3>${ps.map(p=>`<div class="row"><div>${p.name}<p>${p.job} · ${p.id}</p></div>${btn('Open',`openProfile('${p.id}')`,'link')}</div>`).join('')}<h3 style="margin-top:20px">Requests · ${rs.length}</h3>${requestTable(rs)}${!ps.length&&!rs.length?'<p class="sub">No matching records in your current role’s scope.</p>':''}`)}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Download prepared.')}const csv=rows=>rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');function peopleCSV(){return csv([['Employee ID','Name','Job family','Location','Employment'],...visiblePeople().map(p=>[p.id,p.name,p.dept,currentLocation(p),p.employment])])}function exportRequests(){download('requests.csv',csv([['ID','Employee','Type','Leave / allowance type','Status','Owner'],...visibleRequests().map(r=>[r.id,pby(r.person).name,r.type,['Leave','Shift allowance'].includes(r.type)?leaveTypeLabel(r):'',r.status,r.owner])]))}function saveView(){state.views.push({name:tab,query,role});save();toast('View saved: '+tab)}function resetDemo(){modal('Reset demonstration data','<p>This removes requests and changes made in this browser and restores the fictional sample records.</p>',btn('Cancel',"$('#dialog').close()")+btn('Reset',"state=structuredClone(initial);save();$('#dialog').close();render();toast('Demo reset')",'primary'))}function login(e){e.preventDefault();const p=people.find(p=>p.id===$('#empid').value.trim().toUpperCase());if(!p)return toast('Use a demo ID such as PSU-3105, PSU-4210, or PSU-1042.');if(!['PSU-3105','PSU-4210','PSU-1042','AGY-081'].includes(p.id))return toast('Kiosk demo supports PSU-3105, PSU-4210, PSU-1042, or AGY-081.');role=p.id==='PSU-3105'?'Plant worker':p.id==='PSU-4210'?'Technician / field':p.id==='AGY-081'?'Contractor administrator':'Employee';try{sessionStorage.setItem('samanvay-demo-role',role)}catch{};signedOut=false;page='Home';render()}
let idle;function activity(){clearTimeout(idle);idle=setTimeout(()=>{signedOut=true;$('#leaveBalanceAlert')?.close();$('#dialog').close();render();toast('Demo session ended after 15 minutes of inactivity.')},15*60*1000)}document.addEventListener('click',activity);document.addEventListener('keydown',activity);activity();lang=localStorage.getItem('samanvay-language')||state.preferences?.[self()]?.language||'en';render();

function switchRole(value){hierarchyFocus=null;try{sessionStorage.setItem('samanvay-demo-role',value)}catch{};if(location.hash.startsWith('#/profile'))history.replaceState(null,'',location.pathname+location.search);mobileNavOpen=false;document.body.style.overflow='';role=value;lang=localStorage.getItem('samanvay-language')||state.preferences?.[self()]?.language||'en';page='Home';tab='All requests';query='';render()} function toggleLanguage(){setAppLanguage(lang==='en'?'hi':'en')}

function currentLocation(p){return state.events[p.id]?.find(e=>e.location)?.location||p.location}function applyQuery(value){query=value;render()}function applyLocation(value){filter=value;render()}function showViews(){const vs=state.views.filter(v=>v.role===role);modal('Saved views',vs.length?vs.map((v,i)=>`<div class="row"><div>${esc(v.name)}<p>${esc(v.query||'All matching records')}</p></div>${btn('Open',`loadView(${state.views.indexOf(v)})`,'link')}</div>`).join(''):'<p>No saved views for this role. Set a filter and choose Save view.</p>')}function loadView(i){const v=state.views[i];if(!v||v.role!==role)return;tab=v.name;query=v.query;$('#dialog').close();render()}

function searchDirectory(){applyQuery(document.querySelector('[aria-label="Search employee directory"]').value)}function searchRequests(){applyQuery(document.querySelector('[aria-label="Filter requests"]').value)}

// Organisation communications are scoped to the current demo employee.
let orgView='All items',orgType='All types',orgSearch='',orgSelected='',orgEdits={};
function orgRecords(){state.orgMessages??={};if(!state.orgMessages[self()]){const p=person(),agency=p.employment==='Agency contract';state.orgMessages[self()]=[
{id:self()+'-comp',type:'Compensation',title:agency?'Contract rate communication':'Compensation change letter',sender:agency?'Contractor Coordination':'Compensation & Benefits',created:'31 Oct 2026',effective:'01 Nov 2026',summary:agency?'Review the contractor’s rate communication for your deployment.':'Your revised compensation statement is available for review.',body:agency?'A sample rate communication has been issued by your contractor for the current deployment. This is not a PSU employee salary or benefit entitlement. Please review the demonstration document and acknowledge receipt.':'Following the annual compensation review, your revised compensation statement is ready. Please review the attached letter, including the effective date and the components listed, and acknowledge receipt. You may add a comment or ask a question before submitting.',changes:agency?[['Issued by','Shakti Technical Services'],['Relationship','Agency contract'],['Applies to','Current deployment']]:[['Effective from','01 Nov 2026'],['Revision','As detailed in the sample letter'],['Issued by','Compensation & Benefits']],document:'Compensation-change-letter.txt',status:'Action required',read:false,archived:false,comments:[],history:['31 Oct 2026 · Issued by '+(agency?'Contractor Coordination':'Compensation & Benefits')]},
{id:self()+'-transfer',type:'Transfer',title:'Team transfer notification',sender:'HR · Establishment',created:'30 Oct 2026',effective:'09 Nov 2026',summary:'Review your proposed move to a new team and reporting arrangement.',body:'You have been notified of a sample team reassignment. Review the current and proposed team details, reporting instructions, and effective date in the attached communication. Acknowledgement records receipt only; it does not execute a transfer or change your service record.',changes:[['Current team',p.dept],['New team','Operations Support'],['Reporting contact','Establishment office'],['Effective from','09 Nov 2026']],document:'Team-transfer-notification.txt',status:'Action required',read:false,archived:false,comments:[],history:['30 Oct 2026 · Issued by HR · Establishment']},
{id:self()+'-promotion',type:'Promotion',title:agency?'Role progression communication':'Promotion notification',sender:agency?'Contractor Coordination':'HR · Career Progression',created:'29 Oct 2026',effective:'01 Dec 2026',summary:agency?'Your contractor has shared a sample role progression update.':'A career progression communication is ready for your review.',body:agency?'Your contractor has shared a demonstration role progression communication. Review the sample document and acknowledge receipt. This does not change your employment relationship or confer PSU employee entitlements.':'Congratulations on your sample career progression notification. Review the proposed role, effective date, and joining requirements in the attached letter. You can add a comment and acknowledge receipt. This demonstration does not amend your grade, salary, or service record.',changes:[['Employee',p.name],['Role',agency?'Senior Contract Electrician':'Senior '+p.job],['Effective from','01 Dec 2026'],['Next step','Review letter and acknowledge receipt']],document:'Promotion-notification.txt',status:'Action required',read:false,archived:false,comments:[],history:['29 Oct 2026 · Issued by '+(agency?'Contractor Coordination':'HR · Career Progression')]}
];save()}return state.orgMessages[self()]}
function orgUnread(){return orgRecords().filter(m=>!m.read&&!m.archived).length}
function orgMessage(id){return orgRecords().find(m=>m.id===id)}
function orgCapture(){const field=$('#orgComment'),check=$('#orgAgree');if(orgSelected&&field)orgEdits[orgSelected]={comment:field.value,agree:!!check?.checked}}
function orgStamp(){return new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'})+' IST'}
function openOrgMessages(){orgView='All items';orgType='All types';orgSearch='';const first=orgRecords().find(m=>!m.archived);orgSelected=first?.id||'';if(first){first.read=true;save()}go('Organisation Messages')}
function orgChoose(id){orgCapture();const m=orgMessage(id);if(!m)return;orgSelected=id;if(!m.read){m.read=true;save()}render();if(window.innerWidth<760)$('#orgDetail')?.scrollIntoView({behavior:'smooth',block:'start'})}
function orgSetView(v){orgCapture();orgView=v;orgSelected='';render()}
function orgFilter(event){event.preventDefault();orgCapture();orgSearch=$('#orgSearch').value;orgType=$('#orgType').value;orgSelected='';render()}
function orgMessagesPage(){const all=orgRecords(),active=all.filter(m=>!m.archived),counts={'All items':active.length,'Action required':active.filter(m=>m.status!=='Submitted').length,'Submitted':active.filter(m=>m.status==='Submitted').length,'Archive':all.filter(m=>m.archived).length};let list=all.filter(m=>(orgView==='Archive'?m.archived:!m.archived)&&(orgView==='Action required'?m.status!=='Submitted':orgView==='Submitted'?m.status==='Submitted':true)&&(orgType==='All types'||m.type===orgType)&&(`${m.title} ${m.sender} ${m.id}`.toLowerCase().includes(orgSearch.toLowerCase())));const selected=list.find(m=>m.id===orgSelected);return heading(tr('Organisation messages','संगठन के संदेश'),'Your letters, people updates, and acknowledgements in one place.',`<span class="org-private">♙ Private to ${esc(person().name)}</span>`)+`<div class="org-workspace"><aside class="org-folders"><div class="org-folders-title"><svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M3 8l9-5 9 5v12H3zM3 8l9 7 9-7"/></svg><strong>My messages</strong></div><nav aria-label="Message folders">${Object.keys(counts).map(v=>`<button class="${v===orgView?'chosen':''}" onclick="orgSetView('${v}')"><span>${{'All items':'▤','Action required':'◷',Submitted:'✓',Archive:'▣'}[v]} &nbsp; ${v}</span><small>${counts[v]}</small></button>`).join('')}</nav><p>Organisation-issued updates.<br>Your responses stay with each message.</p><div class="org-demo-note">DEMO WORKSPACE<br>Fictional letters · Responses saved in this browser only.</div></aside><section class="org-list" aria-label="Organisation message list"><div class="org-list-head"><h2>${orgView}</h2><span>${list.length} items</span></div><form onsubmit="orgFilter(event)" class="org-search"><label class="sr-only" for="orgSearch">Search organisation messages</label><input id="orgSearch" placeholder="Search messages…" value="${esc(orgSearch)}"><div><label class="sr-only" for="orgType">Message type</label><select id="orgType"><option>All types</option>${['Compensation','Transfer','Promotion'].map(t=>`<option ${orgType===t?'selected':''}>${t}</option>`).join('')}</select><button type="submit" title="Apply message filters">Search</button></div></form><div class="org-items">${list.length?list.map(m=>`<button class="org-item ${m.id===orgSelected?'selected':''} ${!m.read?'unread':''}" onclick="orgChoose('${m.id}')" aria-pressed="${m.id===orgSelected}"><div class="org-item-meta"><span>${esc(m.type)}</span><time>${m.created}</time></div><strong>${!m.read?'<i aria-label="Unread"></i>':''}${esc(m.title)}</strong><p>${esc(m.summary)}</p><div class="org-item-bottom"><span>${esc(m.sender)}</span>${badge(m.status)}</div></button>`).join(''):'<div class="org-no-items"><strong>No messages here</strong><p>Try another folder or adjust your search.</p></div>'}</div></section><section class="org-detail" id="orgDetail" aria-label="Selected message">${selected?orgDetail(selected):`<div class="org-detail-empty"><div>✉</div><h2>Your updates, all together.</h2><p>Select a message to review the letter,<br>add a comment, and acknowledge receipt.</p><span>Compensation &nbsp; · &nbsp; Transfers &nbsp; · &nbsp; Promotions</span></div>`}</section></div>`}
function orgDetail(m){const edit=orgEdits[m.id]||{comment:m.draft||'',agree:false};return `<div class="org-detail-top"><div><span class="eyebrow">${esc(m.type)} COMMUNICATION</span><div class="org-detail-status">${badge(m.status)}${m.archived?'<span class="badge">Archived</span>':''}<span>${esc(m.id)}</span></div></div>${m.archived?btn('Restore',`orgArchive('${m.id}',false)`):btn('Archive',`orgArchive('${m.id}',true)`,'org-archive')}</div><div class="org-detail-scroll"><h2 class="org-letter-title">${esc(m.title)}</h2><p class="org-letter-for">For ${esc(person().name)} · ${esc(self())}</p><div class="org-letter-meta"><span><small>FROM</small>${esc(m.sender)}</span><span><small>CREATED</small>${m.created}</span><span><small>EFFECTIVE</small>${m.effective}</span></div><p class="org-letter-body">${esc(m.body)}</p><div class="org-change-summary">${m.changes.map(([label,val])=>`<div><small>${esc(label)}</small><strong>${esc(val)}</strong></div>`).join('')}</div><h3 class="org-section-title">Documents</h3><div class="org-document"><span class="org-doc-icon">▤</span><div><button class="link" onclick="orgPreview('${m.id}')">${esc(m.document)}</button><small>Demonstration letter · Text document</small></div>${btn('Download',`orgDownload('${m.id}')`,'link')}</div>${!m.archived?`<div class="org-ack"><input id="orgAgree" type="checkbox" ${m.status==='Submitted'?'checked disabled':edit.agree?'checked':''} onchange="orgCapture()"><label for="orgAgree">${m.status==='Submitted'?'Receipt acknowledged':'I have reviewed this communication and acknowledge receipt.'}<small>This acknowledges receipt only. It does not approve or execute an employment change.</small></label></div><label class="org-comment-label" for="orgComment">${m.status==='Submitted'?'Add another comment':'Comment'} <span>(optional)</span></label><textarea id="orgComment" maxlength="2000" placeholder="Add a comment or ask HR a question…" oninput="orgCapture()">${esc(edit.comment)}</textarea><p class="org-comment-help">${m.draft?'You have a saved draft. ':' '}${m.status==='Submitted'?'Comments will be added to the conversation.':'Submit to acknowledge receipt; Save for later keeps your draft.'}</p>`:'<div class="callout">This message is archived. Restore it to add a comment or submit an acknowledgement.</div>'}${m.comments.length?`<h3 class="org-section-title">Conversation <span class="badge">${m.comments.length}</span></h3><div class="org-conversation">${m.comments.map(c=>`<article><div class="person"><span class="avatar">${initials(c.author)}</span><div><strong>${esc(c.author)}</strong><small>${esc(c.date)}</small></div></div><p data-no-translate>${esc(c.text)}</p></article>`).join('')}</div>`:''}<details class="org-history"><summary>Activity history · ${m.history.length} events</summary>${m.history.map(h=>`<p>${esc(h)}</p>`).join('')}</details></div>${!m.archived?`<div class="org-detail-actions">${btn(m.status==='Submitted'?'Submit comment':'Submit',`orgSubmit('${m.id}')`,'primary')}${btn('Save for later',`orgSaveDraft('${m.id}')`)}${btn('Cancel',`orgCancel('${m.id}')`)}<small>Cancel discards unsaved edits.</small></div>`:''}`}
function orgSubmit(id){orgCapture();const m=orgMessage(id),edit=orgEdits[id]||{};if(!m||m.archived)return;if(m.status!=='Submitted'&&!edit.agree){toast('Please acknowledge receipt before submitting.');$('#orgAgree')?.focus();return}const text=(edit.comment||'').trim();if(m.status==='Submitted'&&!text){toast('Enter a comment to submit.');$('#orgComment')?.focus();return}if(text)m.comments.push({author:person().name,text,date:orgStamp()});const first=m.status!=='Submitted';m.status='Submitted';m.read=true;m.draft='';m.history.push(orgStamp()+' · '+(first?'Receipt acknowledged':'Comment added')+' by '+person().name);delete orgEdits[id];audit(`Organisation message ${id}: ${first?'acknowledgement submitted':'comment submitted'}`);save();if(orgView==='Action required')orgView='All items';render();toast(first?'Acknowledgement submitted.':'Comment submitted.')}
function orgSaveDraft(id){orgCapture();const m=orgMessage(id);if(!m||m.archived)return;m.draft=orgEdits[id]?.comment||'';m.history.push(orgStamp()+' · Comment draft saved');save();render();toast('Draft saved in this browser. No response submitted.')}
function orgCancel(id){delete orgEdits[id];orgSelected='';render();toast('Unsaved edits discarded. The message remains in your inbox.')}
function orgArchive(id,archived){orgCapture();const m=orgMessage(id);if(!m)return;if(archived&&orgEdits[id]?.comment)m.draft=orgEdits[id].comment;delete orgEdits[id];m.archived=archived;m.history.push(orgStamp()+' · '+(archived?'Archived':'Restored')+' by '+person().name);audit(`Organisation message ${id}: ${archived?'archived':'restored'}`);save();orgSelected='';render();toast(archived?'Message archived. You can restore it from Archive.':'Message restored to All items.')}
function orgLetterText(m){return ['NRL · SAMANVAY HRMS','DEMONSTRATION DOCUMENT — NOT AN OFFICIAL LETTER','',m.title,'Employee: '+person().name+' · '+self(),'Issued by: '+m.sender,'Created: '+m.created,'Effective: '+m.effective,'',m.body,'',...m.changes.map(([k,v])=>k+': '+v),'','Acknowledgement records receipt only. No real employment or payroll change is executed.'].join('\n')}
function orgPreview(id){const m=orgMessage(id);if(!m)return;orgCapture();modal('Document preview',`<pre class="org-letter-preview">${esc(orgLetterText(m))}</pre>`,btn('Download',`orgDownload('${id}')`)+btn('Close',"$('#dialog').close()",'primary'))}
function orgDownload(id){const m=orgMessage(id);if(m)download(m.document,orgLetterText(m))}

function isMobileNavigation(){return window.matchMedia('(max-width:720px)').matches}
function syncSidebar(){const shell=$('.shell'),sidebar=$('#appSidebar'),toggle=$('.menuToggle'),backdrop=$('.nav-backdrop'),close=$('.sidebarClose');if(!shell||!sidebar||!toggle)return;const mobile=isMobileNavigation();const expanded=mobile?mobileNavOpen:!sidebarCollapsed;shell.classList.toggle('sidebar-collapsed',sidebarCollapsed);sidebar.classList.toggle('open',mobile&&mobileNavOpen);toggle.setAttribute('aria-expanded',String(expanded));toggle.setAttribute('aria-label',expanded?'Collapse navigation':'Open navigation');toggle.title=expanded?'Collapse navigation':'Open navigation';close.setAttribute('aria-label',mobile?'Close navigation':'Collapse navigation');close.title=mobile?'Close navigation':'Collapse navigation';backdrop.hidden=!(mobile&&mobileNavOpen);document.body.style.overflow=mobile&&mobileNavOpen?'hidden':'';$('.main').inert=mobile&&mobileNavOpen}
function toggleSidebar(){if(isMobileNavigation()){mobileNavOpen=!mobileNavOpen}else{sidebarCollapsed=!sidebarCollapsed;try{localStorage.setItem('samanvay-sidebar-collapsed',String(sidebarCollapsed))}catch{}}syncSidebar();if(isMobileNavigation()&&mobileNavOpen)$('.sidebarClose')?.focus()}
function closeSidebar(){if(isMobileNavigation()){mobileNavOpen=false}else{sidebarCollapsed=true;try{localStorage.setItem('samanvay-sidebar-collapsed','true')}catch{}}syncSidebar();$('.menuToggle')?.focus()}
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileNavOpen){event.preventDefault();closeSidebar()}});
window.addEventListener('resize',()=>{if(!isMobileNavigation())mobileNavOpen=false;syncSidebar()});

document.addEventListener('keydown',event=>{if(event.key!=='Tab'||!mobileNavOpen)return;const controls=[...$('#appSidebar').querySelectorAll('button,a,input,select,textarea,[tabindex]')].filter(el=>!el.disabled&&el.tabIndex>=0);const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}});

// Personal workspace and account popover. Data remains scoped to the demo person.
function personalProfile(){const p=person();return {preferredName:p.name,email:p.name.toLowerCase().replaceAll(' ','.')+'@example.invalid',phone:'••••••4821',address:'Staff township · Demonstration address',city:'Assam',emergencyName:'Demo family contact',emergencyRelation:'Family',emergencyPhone:'••••••9410',about:'Working together to keep our people and operations moving.',...(state.personalProfiles?.[self()]||{})}}
function accountName(){return personalProfile().preferredName||person().name}
function accountPanel(){const p=person();return `<section class="accountPanel" id="accountPanel" aria-label="Your account" hidden><div class="account-panel-banner"><span>YOUR WORKSPACE</span><span class="account-local">DEMO</span></div><div class="account-panel-person"><span class="avatar">${initials(accountName())}</span><div><strong data-no-translate>${esc(accountName())}</strong><p>${esc(p.job)}</p><small>${self()} · ${esc(p.dept)}</small></div></div><div class="account-panel-location">⌖ ${esc(currentLocation(p))}</div><button class="account-view-profile" onclick="navigateProfile('overview')">View profile <span>↗</span></button><div class="account-shortcuts"><button onclick="accountRequests()"><span>☑</span><div>My requests<small>Track applications and approvals</small></div><span>→</span></button><button onclick="navigateProfile('preferences')"><span>⚙</span><div>Account preferences<small>Language and workspace details</small></div><span>→</span></button><button onclick="closeAccount();openOrgMessages()"><span>▤</span><div>Organisation messages<small>Your letters and acknowledgements</small></div><span>→</span></button></div><div class="account-panel-footer"><span>NRL · Samanvay</span><button onclick="accountSignOut()">Sign out ↪</button></div></section>`}
function toggleAccount(){accountOpen=!accountOpen;const panel=$('#accountPanel'),trigger=$('.accountTrigger');panel.hidden=!accountOpen;trigger.setAttribute('aria-expanded',String(accountOpen));if(accountOpen)panel.querySelector('button')?.focus()}
function closeAccount(focus=false){accountOpen=false;const panel=$('#accountPanel'),trigger=$('.accountTrigger');if(panel)panel.hidden=true;trigger?.setAttribute('aria-expanded','false');if(focus)trigger?.focus()}
function accountSignOut(){closeAccount();if(location.hash.startsWith('#/profile'))history.replaceState(null,'',location.pathname+location.search);try{sessionStorage.removeItem('samanvay-demo-role')}catch{};signedOut=true;$('#dialog').close();render()}
function accountRequests(){closeAccount();go('My Work');query=person().name;render()}
document.addEventListener('click',event=>{if(accountOpen&&!event.target.closest('.accountWrap'))closeAccount()});
document.addEventListener('keydown',event=>{if(!accountOpen)return;if(event.key==='Escape'){event.preventDefault();closeAccount(true)}else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){const items=[...$('#accountPanel').querySelectorAll('button')],i=items.indexOf(document.activeElement);event.preventDefault();items[event.key==='Home'?0:event.key==='End'?items.length-1:(i+(event.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}});
document.addEventListener('focusin',event=>{if(accountOpen&&!event.target.closest('.accountWrap'))closeAccount()});
const userProfileSections=[['overview','Overview','⌂'],['personal','Personal information','♙'],['work','Work & organisation','▦'],['hierarchy','Reporting hierarchy','♧'],['service','Service history','◷'],['documents','My documents','▤'],['preferences','Account preferences','⚙']];
function navigateProfile(section='overview'){if(!userProfileSections.some(s=>s[0]===section))section='overview';closeAccount();mobileNavOpen=false;userProfileSection=section;page='My Profile';history.pushState(null,'','#/profile/'+section);render();window.scrollTo(0,0)}
function readProfileRoute(){if(!location.hash.startsWith('#/profile'))return;const section=location.hash.split('/')[2]||'overview';userProfileSection=userProfileSections.some(s=>s[0]===section)?section:'overview';page='My Profile';render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/joining/')){render();window.scrollTo(0,0)}else readProfileRoute()});window.addEventListener('popstate',()=>{if(location.hash.startsWith('#/profile'))readProfileRoute();else if(page==='My Profile'){page='Home';render()}});
function profilePairs(pairs){return `<dl class="self-pairs">${pairs.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd data-i18n-user>${esc(v)}</dd></div>`).join('')}</dl>`}
function selfCard(title,subtitle,body,action=''){return `<section class="self-card"><div class="self-card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`}
function userProfilePage(){const p=person(),v=personalProfile(),active=userProfileSections.find(s=>s[0]===userProfileSection);return `<div class="self-heading"><div><div class="eyebrow">MY PERSONAL WORKSPACE</div><h1>My profile</h1><p class="sub">Your information, your work, and the details that connect them.</p></div>${btn('← Back to home',"go('Home')")}</div><section class="self-hero"><div class="self-hero-main"><span class="self-large-avatar">${initials(accountName())}<span>✓</span></span><div><div class="self-hero-kicker">${esc(p.category)} <span>·</span> ${esc(p.id)}</div><h2 data-no-translate>${esc(accountName())}</h2><p>${esc(p.job)} <span>·</span> ${esc(p.dept)}</p><div class="self-hero-tags"><span>⌖ ${esc(currentLocation(p))}</span><span>◷ ${esc(p.shift)}</span></div></div></div><div class="self-hero-side"><span class="self-active-dot">● Active assignment</span><strong>${esc(p.employment)}</strong><small>${p.employment==='Agency contract'?'Shakti Technical Services':'NRL · Demonstration workforce'}</small></div></section><div class="self-layout"><aside class="self-navigation"><div class="self-nav-label">PROFILE SECTIONS</div><nav aria-label="Profile sections">${userProfileSections.map(([id,label,icon])=>`<button class="${id===userProfileSection?'selected':''}" ${id===userProfileSection?'aria-current="page"':''} onclick="navigateProfile('${id}')"><span>${icon}</span>${label}<span class="self-nav-arrow">›</span></button>`).join('')}</nav><div class="self-nav-help"><strong>Need to correct a record?</strong><p>HR can help with official employment and identity changes.</p>${btn('Contact HR →',"go('Employee Services')",'link')}</div></aside><div class="self-main"><div class="self-section-heading"><h2>${active[1]}</h2><span>Personal workspace · Sample data</span></div>${userProfileContent(p,v)}<div class="self-local-note">◈ Demonstration profile. Edits are saved in this browser for the selected employee.</div></div></div>`}
function userProfileContent(p,v){switch(userProfileSection){case'overview':return `<div class="self-two-col">${selfCard('About me','A little context beyond your designation.',`<p class="self-about" data-i18n-user>${esc(v.about)}</p>${profilePairs([['Preferred name',v.preferredName],['Work email',v.email]])}`,btn('Edit',"editSelfProfile('about')",'link'))}${selfCard('My assignment','Your current role and reporting context.',profilePairs([['Designation',p.job],['Department',p.dept],['Grade',p.grade],['Reporting contact',hierarchyManagerName(p.id)]]),btn('View work →',"navigateProfile('work')",'link'))}</div>${selfCard('Take care of your details','Quick access to the information you use most.',`<div class="self-action-grid">${[['♙','Personal details','Names, contact and emergency details','personal'],['▤','My documents','Letters and reference documents','documents'],['◷','Service history','Appointments, postings and transfers','service']].map(([icon,label,sub,section])=>`<button onclick="navigateProfile('${section}')"><span>${icon}</span><strong>${label}</strong><small>${sub}</small><b>→</b></button>`).join('')}</div>`)}${selfCard('Recent profile activity','Changes made in your personal workspace.',profileActivity())}`;
case'hierarchy':return reportingHierarchy(p);
case'personal':return `<div class="self-two-col">${selfCard('Name & identity','How you appear in your personal workspace.',profilePairs([['Legal name',p.name],['Preferred name',v.preferredName],['Employee ID',p.id],['Government identifiers','Masked in the demonstration']]),btn('Edit preferred name',"editSelfProfile('name')",'link'))}${selfCard('Contact information','Keep your contact details up to date.',profilePairs([['Email address',v.email],['Phone number',v.phone]]),btn('Edit',"editSelfProfile('contact')",'link'))}${selfCard('Emergency contact','Who to reach when you need support.',profilePairs([['Contact name',v.emergencyName],['Relationship',v.emergencyRelation],['Phone number',v.emergencyPhone]]),btn('Edit',"editSelfProfile('emergency')",'link'))}${selfCard('Address','Your current correspondence address.',profilePairs([['Address',v.address],['City / state',v.city]]),btn('Edit',"editSelfProfile('address')",'link'))}</div><div class="self-guidance"><span>ⓘ</span><p>Legal name, government identifiers, and employment changes need HR verification. ${btn('Open employee services →',"go('Employee Services')",'link')}</p></div>`;
case'work':return `<div class="self-two-col">${selfCard('Employment & position','The independent dimensions of your assignment.',profilePairs([['Employment relationship',p.employment],['Employee category',p.category],['Job family',p.dept],['Designation',p.job],['Grade',p.grade],['Work location',currentLocation(p)],['Working pattern',p.shift],['Contractor',p.employment==='Agency contract'?'Shakti Technical Services':'Not applicable']]))}${selfCard('Reporting & team','Your first point of contact for work matters.',`<div class="self-manager"><span class="avatar">${initials(hierarchyManagerName(p.id))}</span><div><strong>${esc(hierarchyManagerName(p.id))}</strong><p>Reporting officer</p></div></div>${profilePairs([['Department',p.dept],['Organisation','NRL · Sample organisation'],['Assignment status','Active']])}${btn('Explore reporting hierarchy →',"navigateProfile('hierarchy')",'link')}`)}</div>`;
case'service':return selfCard('My service book','A date-effective view of your employment journey.',`<div class="timeline">${[...(state.events[p.id]||[]),{date:'01 Apr 2024',title:'Grade revision recorded',note:`Grade ${p.grade} · Illustrative service event`},{date:'01 Jul 2021',title:'Posting confirmed',note:p.location},{date:'15 Jun 2018',title:'Initial appointment',note:p.job}].map(e=>`<div class="event"><small>${esc(e.date)}</small><p><strong>${esc(e.title)}</strong></p><small>${esc(e.note)}</small></div>`).join('')}</div>`);
case'documents':return selfCard('My documents','Sample documents and organisation communications.',`<div class="self-doc-row"><span class="self-doc-symbol">▤</span><div><strong>Appointment reference</strong><p>Demonstration text document · Employee record</p></div>${btn('Preview',"previewSelfDocument()",'link')}</div>${orgRecords().map(m=>`<div class="self-doc-row"><span class="self-doc-symbol">▤</span><div><strong>${esc(m.title)}</strong><p>${m.created} · ${esc(m.sender)}</p></div>${btn('Preview',`orgPreview('${m.id}')`,'link')}</div>`).join('')}`);
case'preferences':return `<div class="self-two-col">${selfCard('Workspace language','Choose your interface language.',`<form class="self-preference-form" onsubmit="saveSelfLanguage(event)"><label for="selfLanguage">Interface language</label><select id="selfLanguage"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="hi" ${lang==='hi'?'selected':''}>Hindi</option></select><p>Hindi covers all interface pages, forms, messages, and menus.</p><button class="primary" type="submit">Save preference</button></form>`)}${selfCard('Account & access','Details for this demonstration session.',profilePairs([['Employee ID',self()],['Current demo role',role],['Workspace','NRL · Samanvay'],['Session','Browser-local demonstration']])+`<p class="self-access-note">Role switching is a preview tool. Production account security is not implemented.</p>${btn('Sign out of demo',"accountSignOut()")}`)}</div>`;default:return''}}
function profileActivity(){const entries=(state.profileActivity?.[self()]||[]).slice().reverse().slice(0,5);return entries.length?`<div class="self-activity-list">${entries.map(e=>`<div><span>✓</span><div><strong>${esc(e.action)}</strong><small>${esc(e.date)}</small></div></div>`).join('')}</div>`:'<div class="self-no-activity"><span>◷</span><p>No profile changes yet.<br><small>Updates you save will appear here.</small></p></div>'}
function editSelfProfile(kind){const v=personalProfile(),config={about:{title:'Edit about me',fields:[['about','About me','textarea']]},name:{title:'Edit preferred name',fields:[['preferredName','Preferred name','text']]},contact:{title:'Edit contact information',fields:[['email','Email address','email'],['phone','Phone number','tel']]},emergency:{title:'Edit emergency contact',fields:[['emergencyName','Contact name','text'],['emergencyRelation','Relationship','text'],['emergencyPhone','Phone number','tel']]},address:{title:'Edit correspondence address',fields:[['address','Address','textarea'],['city','City / state','text']]}}[kind];if(!config)return;modal(config.title,`<form id="selfEditForm" onsubmit="saveSelfProfile(event,'${kind}')"><div class="formgrid">${config.fields.map(([key,label,type])=>`<label class="field full">${label}${type==='textarea'?`<textarea name="${key}" required maxlength="600">${esc(v[key])}</textarea>`:`<input name="${key}" type="${type}" ${type==='tel'?'pattern="[0-9+ ]{7,20}"':'required'} maxlength="${type==='tel'?20:120}" value="${type==='tel'&&v[key].includes('•')?'':esc(v[key])}" placeholder="${type==='tel'?'Leave blank to keep the masked demo number':''}">`}</label>`).join('')}</div><p class="self-form-note">Use fictional details in this demonstration. Changes are saved only for this employee in this browser.</p><div class="modalfoot" style="padding:18px 0 0;border:0"><button type="button" onclick="$('#dialog').close()">Cancel</button><button class="primary" type="submit">Save changes</button></div></form>`)}
function saveSelfProfile(event,kind){event.preventDefault();const form=$('#selfEditForm');if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));for(const k of Object.keys(values)){values[k]=values[k].trim();if(!values[k])delete values[k]}state.personalProfiles??={};state.personalProfiles[self()]={...(state.personalProfiles[self()]||{}),...values};const labels={about:'About me updated',name:'Preferred name updated',contact:'Contact information updated',emergency:'Emergency contact updated',address:'Correspondence address updated'};state.profileActivity??={};state.profileActivity[self()]??=[];state.profileActivity[self()].push({action:labels[kind],date:orgStamp()});audit(`${self()}: ${labels[kind]}`);save();$('#dialog').close();render();toast('Profile changes saved.')}
function previewSelfDocument(){const text=`NRL · SAMANVAY HRMS\nDEMONSTRATION APPOINTMENT REFERENCE\n\nEmployee: ${person().name}\nEmployee ID: ${self()}\nDesignation: ${person().job}\nEmployment: ${person().employment}\n\nSample document only. Not an official appointment order.`;modal('Appointment reference',`<pre class="org-letter-preview">${esc(text)}</pre>`,btn('Download',"downloadSelfAppointment()")+btn('Close',"$('#dialog').close()",'primary'))}
function downloadSelfAppointment(){download('appointment-reference.txt',`DEMONSTRATION DOCUMENT\n${person().name} · ${self()}\n${person().job}\nNot an official appointment order.`)}
function saveSelfLanguage(event){event.preventDefault();setAppLanguage($('#selfLanguage').value);toast('Language preference saved.')}
readProfileRoute();

function applyLanguage(root=document.body){window.HRMSI18N.apply(root,lang);const button=$('.languageToggle');if(button){button.textContent=lang==='hi'?'EN':'हि';button.setAttribute('aria-label',lang==='hi'?'अंग्रेज़ी में बदलें':'Switch to Hindi');button.title=lang==='hi'?'Switch to English':'हिन्दी में बदलें'}const select=$('#selfLanguage');if(select)select.value=lang}
function setAppLanguage(value){document.querySelectorAll('input,select,textarea').forEach(field=>field.setCustomValidity?.(''));lang=value==='hi'?'hi':'en';localStorage.setItem('samanvay-language',lang);state.preferences??={};state.preferences[self()]={...(state.preferences[self()]||{}),language:lang};save();applyLanguage()}
window.HRMSI18N.start();applyLanguage();
// Browser validation messages follow the selected interface language too.
document.addEventListener('invalid',event=>{const field=event.target;if(lang!=='hi'||!field.setCustomValidity)return;const validity=field.validity;let message='कृपया मान्य जानकारी दर्ज करें।';if(validity.valueMissing)message=field.tagName==='SELECT'?'कृपया एक विकल्प चुनें।':'कृपया यह जानकारी भरें।';else if(validity.typeMismatch&&field.type==='email')message='कृपया मान्य ईमेल पता दर्ज करें।';else if(validity.rangeUnderflow)message=`कृपया ${field.min} या उससे अधिक मान दर्ज करें।`;else if(validity.rangeOverflow)message=`कृपया ${field.max} या उससे कम मान दर्ज करें।`;else if(validity.patternMismatch)message='कृपया निर्धारित प्रारूप में जानकारी दर्ज करें।';field.setCustomValidity(message)},true);
for(const type of ['input','change'])document.addEventListener(type,event=>{event.target.setCustomValidity?.('')},true);

// Grouped leave selection with per-type balances and recoverable balance alerts.
let leaveEditor=null;
function leaveTypeLabel(request){return window.LeaveModel.get(request.leaveType||'annual')?.name||request.leaveTypeName||'Annual Leave'}
function leaveEntry(personId,typeId,excludeId=''){return window.LeaveModel.ledger(state,people,personId,typeId,excludeId)}
function leaveCount(value){return Number(value).toLocaleString('en-IN',{maximumFractionDigits:1})}
function leaveDaysLabel(value){return leaveCount(value)+(Number(value)===1?' day':' days')}
function leaveBalanceLabel(entry){if(!entry.configured)return 'Not configured';if(entry.available!==null)return leaveDaysLabel(entry.available);return entry.type.mode==='unpaid'?'Unpaid':entry.type.mode==='allowance'?'No leave deduction':'Policy approval'}
function leaveAction(text,code,cls=''){return `<button type="button" class="${cls}" onclick="${code}">${text}</button>`}
function leaveRequestForm(existing=null,requestType='Leave'){const r=existing||{},employee=r.person||self(),initialType=r.leaveType||(requestType==='Shift allowance'?'evening':'annual'),type=window.LeaveModel.get(initialType),entry=leaveEntry(employee,initialType,r.id||'');leaveEditor={id:r.id||'',person:employee,selected:type?type.id:'annual',group:type?.group||'Personal Leave',query:''};const choices=['Leave','Shift allowance','Attendance correction','Overtime','Claim','Certificate','Helpdesk',...(role==='HR officer'?['Transfer']:[])];modal(existing?'Edit & resubmit request':'Apply for leave',`<form id="requestform" onsubmit="submitRequest(event,false,'${r.id||''}')"><input name="leaveType" id="leaveTypeValue" type="hidden" value="${leaveEditor.selected}"><div class="leave-form-layout"><section class="leave-main"><div class="leave-form-intro"><span class="eyebrow">TIME AWAY, MADE CLEAR</span><h3>Choose the right leave for your plans.</h3><p>Compare your balances, select a type, and review the days before submitting.</p></div><div class="formgrid leave-meta"><label class="field">Request type<select name="type" id="leaveRequestKind" onchange="requestForm(this.value)">${choices.map(t=>`<option value="${t}" ${(type?.mode==='allowance'?'Shift allowance':'Leave')===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Employee<select name="person" id="leaveEmployee" onchange="changeLeaveEmployee(this.value)">${(role==='HR officer'?visiblePeople():[person()]).map(p=>`<option value="${p.id}" ${employee===p.id?'selected':''}>${p.name} · ${p.id}</option>`).join('')}</select></label></div><div class="leave-picker"><div class="leave-picker-heading"><label for="leaveTypeSearch">Leave / allowance type</label><span>Balance beside every option</span></div><div class="leave-picker-search"><span>⌕</span><input id="leaveTypeSearch" placeholder="Search leave types…" oninput="filterLeaveTypes(this.value)" onkeydown="if(event.key==='Enter')event.preventDefault()"></div><div class="leave-categories" id="leaveCategories">${leaveCategoryButtons()}</div><div id="leaveOptions" class="leave-options" role="radiogroup" aria-label="Leave types">${leaveOptionRows()}</div></div><div id="leaveSelectionSummary" aria-live="polite"></div><div class="formgrid leave-dates"><label class="field">From<input name="from" id="leaveFrom" type="date" required value="${r.from||'2026-11-03'}" onchange="refreshLeaveSummary()"></label><label class="field">To<input name="to" id="leaveTo" type="date" required value="${r.to||'2026-11-04'}" onchange="refreshLeaveSummary()"></label><label class="field full">Reason / details<textarea name="reason" required maxlength="1500" placeholder="Provide the details needed to review this request.">${esc(r.reason||'')}</textarea></label><label class="field full">Supporting document (optional)<input name="attachment" type="file" accept=".pdf,.png,.jpg,.txt"><small class="sub">Demo stores the filename only; no file is uploaded.</small></label>${role==='HR officer'?'<label class="field full">Assisted submission<input name="assisted" placeholder="Optional: employee requested assistance"></label>':''}</div></section><aside class="leave-balances" id="leaveBalancesAside">${leaveBalanceSidebar()}</aside></div><div class="leave-form-footer"><p>Calendar days · Demo company policy</p><div>${leaveAction('Cancel',"$('#dialog').close()")}${leaveAction('Save draft',`submitRequest(null,true,'${r.id||''}')`)}<button class="primary" id="leaveSubmit" type="submit">${existing?'Resubmit request':'Submit request'}</button></div></div></form>`);$('#dialog').classList.add('leave-dialog');refreshLeaveSummary();applyLanguage($('#dialog'));if(!entry.configured)showLeaveBalanceAlert({code:'unconfigured',type,entry});else if(entry.available===0)showLeaveBalanceAlert({code:'exhausted',type,entry})}
function leaveCategoryButtons(){return ['Personal Leave','Family Leave','Time Off','Shift & On-Call Allowance'].map(group=>leaveAction(group,`setLeaveCategory('${group}')`,leaveEditor.group===group&&!leaveEditor.query?'selected':'')).join('')}
function leaveOptionRows(){const matches=window.LeaveModel.types.filter(t=>leaveEditor.query?`${t.name} ${t.group} ${window.HRMSI18N.translate(t.name)}`.toLowerCase().includes(leaveEditor.query.toLowerCase()):t.group===leaveEditor.group);return matches.length?matches.map(t=>{const entry=leaveEntry(leaveEditor.person,t.id,leaveEditor.id),zero=entry.configured&&entry.available===0;return `<label class="leave-option ${t.id===leaveEditor.selected?'selected':''} ${zero?'exhausted':''}"><input type="radio" name="leaveChoice" value="${t.id}" ${t.id===leaveEditor.selected?'checked':''} onchange="chooseLeaveType('${t.id}')"><span class="leave-option-name"><strong>${esc(t.name)}</strong>${leaveEditor.query?`<small>${t.group}</small>`:''}${entry.pending?`<small>${leaveDaysLabel(entry.pending)} reserved by pending requests</small>`:''}</span><span class="leave-option-balance ${zero?'zero':''}"><strong>${esc(leaveBalanceLabel(entry))}</strong>${zero?'<small>Exhausted</small>':entry.available!==null?'<small>Available to request</small>':''}</span></label>`}).join(''):'<div class="leave-no-options">No matching leave types. Try another search.</div>'}
function leaveBalanceSidebar(){const all=window.LeaveModel.types.filter(t=>t.mode!=='allowance');return `<div class="leave-balance-title"><span>◷</span><div><h3>Your leave balances</h3><p>Available to request</p></div></div><p class="leave-balance-caption">${esc(pby(leaveEditor.person).name)} · ${leaveEditor.person}</p><div class="leave-balance-list">${['Personal Leave','Family Leave','Time Off'].map(group=>`<section><h4>${group}</h4>${all.filter(t=>t.group===group).map(t=>{const e=leaveEntry(leaveEditor.person,t.id,leaveEditor.id);return `<div class="leave-balance-line ${t.id===leaveEditor.selected?'selected':''}"><span>${t.name}</span><strong class="${e.available===0?'zero':''}">${esc(leaveBalanceLabel(e))}</strong></div>`}).join('')}</section>`).join('')}</div><div class="leave-balance-note"><strong>Demo balances only</strong><p>Pending requests reserve days. Balances are deducted only after approval.</p><p>Entitlements must follow the company’s adopted policy.</p></div>`}
function renderLeaveOptions(preserveScroll=true){const offset=preserveScroll?$('#leaveOptions').scrollTop:0;$('#leaveCategories').innerHTML=leaveCategoryButtons();$('#leaveOptions').innerHTML=leaveOptionRows();$('#leaveOptions').scrollTop=offset;applyLanguage($('#dialog'))}
function setLeaveCategory(group){leaveEditor.group=group;leaveEditor.query='';$('#leaveTypeSearch').value='';renderLeaveOptions(false);$('#leaveCategories .selected')?.focus()}
function filterLeaveTypes(value){leaveEditor.query=value.trim();renderLeaveOptions(false)}
function chooseLeaveType(id){const type=window.LeaveModel.get(id);if(!type)return;leaveEditor.selected=id;$('#leaveTypeValue').value=id;$('#leaveRequestKind').value=type.mode==='allowance'?'Shift allowance':'Leave';$('#leaveBalancesAside').innerHTML=leaveBalanceSidebar();refreshLeaveSummary();renderLeaveOptions();document.querySelector('#leaveOptions input:checked')?.focus({preventScroll:true});const entry=leaveEntry(leaveEditor.person,id,leaveEditor.id);if(!entry.configured)showLeaveBalanceAlert({code:'unconfigured',type,entry});else if(entry.available===0)showLeaveBalanceAlert({code:'exhausted',type,entry})}
function changeLeaveEmployee(id){leaveEditor.person=id;$('#leaveBalancesAside').innerHTML=leaveBalanceSidebar();refreshLeaveSummary();renderLeaveOptions();const type=window.LeaveModel.get(leaveEditor.selected),entry=leaveEntry(id,type.id,leaveEditor.id);if(!entry.configured)showLeaveBalanceAlert({code:'unconfigured',type,entry});else if(entry.available===0)showLeaveBalanceAlert({code:'exhausted',type,entry})}
function refreshLeaveSummary(){if(!leaveEditor||!$('#leaveSelectionSummary'))return;const t=window.LeaveModel.get(leaveEditor.selected),e=leaveEntry(leaveEditor.person,t.id,leaveEditor.id),days=window.LeaveModel.countDays($('#leaveFrom').value,$('#leaveTo').value),blocked=!e.configured||e.available===0;$('#leaveSubmit').disabled=blocked;const after=e.available===null?'—':leaveCount(Math.max(0,e.available-Math.max(0,days)));$('#leaveSelectionSummary').innerHTML=`<div class="leave-selection ${blocked?'warn':''}"><div><span>Selected type</span><strong>${t.name}</strong></div><div><span>${t.mode==='allowance'?'Duty days':'Requested days'}</span><strong>${days>0?leaveCount(days):'—'}</strong></div><div><span>${e.available===null?'Balance rule':'Balance after request'}</span><strong>${e.available===null?leaveBalanceLabel(e):leaveDaysLabel(Math.max(0,e.available-Math.max(0,days)))}</strong></div></div>${blocked?`<p class="leave-inline-warning">${!e.configured?'Leave entitlements are not configured for this employee.':'Leave exhausted. Choose another type to continue.'}</p>`:e.available!==null&&days>e.available?'<p class="leave-inline-warning">The requested days exceed the available balance.</p>':t.mode==='unpaid'?'<p class="leave-selection-note">Unpaid leave · Subject to approval · No paid-leave balance is deducted.</p>':t.mode==='approval'?'<p class="leave-selection-note">Case-based approval · No fixed balance is assigned in this demo.</p>':t.mode==='allowance'?'<p class="leave-selection-note">This is a duty allowance request, not leave. No leave days will be deducted.</p>':'<p class="leave-selection-note">Calendar days are counted in this demo. Company holiday and shift rules must be configured.</p>'}`;applyLanguage($('#leaveSelectionSummary'))}
function showLeaveBalanceAlert(issue){let d=$('#leaveBalanceAlert');if(!d){d=document.createElement('dialog');d.id='leaveBalanceAlert';d.className='leave-balance-alert';d.setAttribute('role','alertdialog');d.setAttribute('aria-labelledby','leaveAlertTitle');document.body.appendChild(d)}const unconfigured=issue.code==='unconfigured',insufficient=issue.code==='insufficient',title=unconfigured?'Leave not configured':insufficient?'Insufficient leave balance':'Leave exhausted',entry=issue.entry||{},type=issue.type;d.innerHTML=`<div class="leave-alert-icon">!</div><h2 id="leaveAlertTitle">${title}</h2><p><strong>${esc(type?.name||'Leave')}</strong></p><p>${unconfigured?'Leave entitlements are not configured for this employee. Please contact HR before applying.':insufficient?'The requested days exceed the available balance. Reduce the dates or choose another type.':'You have no available days remaining for this leave type. Choose another type or contact HR.'}</p>${!unconfigured?`<div class="leave-alert-balance"><span>Available to request</span><strong>${leaveDaysLabel(entry.available||0)}</strong>${issue.days?`<span>Requested days</span><strong>${leaveCount(issue.days)}</strong>`:''}</div>${entry.pending?`<p class="leave-alert-pending">${leaveDaysLabel(entry.pending)} reserved by pending requests</p>`:''}`:''}<div class="leave-alert-actions">${leaveAction('Choose another type',"$('#leaveBalanceAlert').close();$('#leaveTypeSearch')?.focus()",'primary')}</div>`;if(!d.open)d.showModal();applyLanguage(d)}
function leaveBalancesOverview(){return `<div class="leave-overview-head"><div><strong>Your leave balances</strong><p>Available to request · Pending requests are reserved</p></div>${btn('Apply for leave',"requestForm('Leave')",'primary')}</div><div class="leave-overview-grid">${window.LeaveModel.types.filter(t=>t.mode!=='allowance').map(t=>{const e=leaveEntry(self(),t.id);return `<div><small>${t.group}</small><strong>${t.name}</strong><span class="${e.available===0?'zero':''}">${leaveBalanceLabel(e)}</span>${e.available===0?'<em>Exhausted</em>':''}</div>`}).join('')}</div><p class="leave-overview-note">Demo balances only. Entitlements must follow the company’s adopted policy.</p>`}

function annualLeaveAvailable(){const entry=leaveEntry(self(),'annual');return entry.configured?entry.available:'—'}

